  </div>
</template>

<script setup lang="ts">
import {
  ref,
  watch,
  onMounted,
  onUnmounted,
} from 'vue';
import { gsap } from 'gsap';
import VueSlider from 'vue-3-slider-component';
import { clamp } from '@/core/utils';

const zoom = ref(1);
const offsetX = ref(0);
const offsetY = ref(0);
const isPanning = ref(false);
const lastX = ref(0);
const lastY = ref(0);

const width = ref(window.innerWidth);
const height = ref(window.innerHeight);
const cx = width.value / 2;
const cy = height.value / 2;
const minZoom = 0.5;
const maxZoom = 1.5;
const zoomStep = 0.25; // sensitivity

const createPathFromCircleAttributes = (r: number) => `M ${cx + r}, ${cy} A ${r},${r} 0 1,0 ${cx - r}, ${cy} A ${r},${r} 0 1,0 ${cx + r}, ${cy}`;

const updateSize = () => {
  width.value = window.innerWidth;
  height.value = window.innerHeight;
};

const onPointerDown = (e: PointerEvent) => {
  if (e.button !== 0) return;

  isPanning.value = true;
  lastX.value = e.clientX;
  lastY.value = e.clientY;

  (e.target as Element).setPointerCapture(e.pointerId);
};

const onPointerMove = (e: PointerEvent) => {
  if (!isPanning.value) return;

  const dx = e.clientX - lastX.value;
  const dy = e.clientY - lastY.value;

  offsetX.value += dx / zoom.value;
  offsetY.value += dy / zoom.value;

  const worldBorder = cx * zoom.value;

  offsetX.value = clamp(offsetX.value, -worldBorder, worldBorder);
  offsetY.value = clamp(offsetY.value, -worldBorder, worldBorder);

  lastX.value = e.clientX;
  lastY.value = e.clientY;
};

const onPointerUp = (e: PointerEvent) => {
  isPanning.value = false;

  (e.target as Element).releasePointerCapture(e.pointerId);
};

const orbits = [
  // {
  //   d: createPathFromCircleAttributes(15),
  // },
  // {
  //   d: createPathFromCircleAttributes(108),
  // },
  {
    d: createPathFromCircleAttributes(241),
    'stroke-dasharray': '12 12',
  },
  {
    d: createPathFromCircleAttributes(338),
    'stroke-dasharray': '14 14',
  },
  {
    d: createPathFromCircleAttributes(426),
    'stroke-dasharray': '15 15',
  },
  {
    d: createPathFromCircleAttributes(513),
    'stroke-dasharray': '17 17',
  },
  {
    d: createPathFromCircleAttributes(599),
    'stroke-dasharray': '19 19',
  },
  {
    d: createPathFromCircleAttributes(689),
    'stroke-dasharray': '21 21',
  },
];

const planets = [
  {
    id: '#Planet1',
    radius: 241, // Distance from center of mass (px)
    period: 10, // Period of resolution (s)
    angleOffset: Math.random() * Math.PI * 2, // Starting point
    moons: [
      {
        id: '#Planet1Moon1',
        radius: 25, // Distance from center of planet (px)
        period: 4, // Period of resolution (s)
        angleOffset: Math.random() * Math.PI * 2,
      },
    ],
  },
  { id: '#Planet2', radius: 338, period: 35, angleOffset: Math.random() * Math.PI * 2 },
  { id: '#Planet3', radius: 426, period: 50, angleOffset: Math.random() * Math.PI * 2 },
  { id: '#Planet4', radius: 513, period: 85, angleOffset: Math.random() * Math.PI * 2 },
  { id: '#Planet5', radius: 599, period: 135, angleOffset: Math.random() * Math.PI * 2 },
  { id: '#Planet6', radius: 689, period: 220, angleOffset: Math.random() * Math.PI * 2 },
];

watch([zoom, offsetX, offsetY], ([z, x, y]) => {
  gsap.to('#Scene', {
    scale: z,
    x,
    y,
    svgOrigin: `${cx} ${cy}`,
    duration: 0.2,
    ease: 'power2.out',
  });
});

onMounted(() => {
  window.addEventListener('resize', updateSize);

  const center = { x: cx, y: cy };
  const bhRadius = 4;
  const starRadius = 85;
  const periodBinary = 2;

  gsap.set([
    '#BlackHole',
    '#Star',
    ...planets.flatMap((p) => [p.id].concat((p?.moons ?? []).map((m) => m.id))),
  ], { xPercent: -50, yPercent: -50 });

  const startTime = performance.now();

  gsap.ticker.add(() => {
    const t = (performance.now() - startTime) / 1000;

    // Binary system
    const angleBH = -(t / periodBinary) * Math.PI * 2 + Math.PI / 4;
    const angleStar = -(t / periodBinary) * Math.PI * 2 + Math.PI + Math.PI / 4;

    const bhPos = {
      x: center.x + bhRadius * Math.cos(angleBH),
      y: center.y + bhRadius * Math.sin(angleBH),
    };
    const starPos = {
      x: center.x + starRadius * Math.cos(angleStar),
      y: center.y + starRadius * Math.sin(angleStar),
    };

    gsap.set('#BlackHole', bhPos);
    gsap.set('#Star', starPos);

    // Planets
    planets.forEach((p) => {
      const angleP = -(t / p.period) * Math.PI * 2 + p.angleOffset;

      const planetPos = {
        x: center.x + p.radius * Math.cos(angleP),
        y: center.y + p.radius * Math.sin(angleP),
      };

      gsap.set(p.id, planetPos);

      // Moons
      if (p.moons) {
        p.moons.forEach((m) => {
          const angleM = -(t / m.period) * Math.PI * 2 + m.angleOffset;
          const moonPos = {
            x: planetPos.x + m.radius * Math.cos(angleM),
            y: planetPos.y + m.radius * Math.sin(angleM),
          };
          gsap.set(m.id, moonPos);
        });
      }
    });
  });
});

onUnmounted(() => {
  window.removeEventListener('resize', updateSize);
});
</script>

<style lang="scss" src="./Planetarium.scss">
